export interface ConnectorConfig {
  /** HubSpot private app access token (env: HUBSPOT_ACCESS_TOKEN) */
  hubspotAccessToken: string
  /** Pre-created HubSpot timeline event template ID */
  eventTemplateId: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface StripeCheckoutSessionCompleted {
  id: string
  customer: {
    email: string
  }
  client_reference_id?: string
}

export interface HubSpotContactResponse {
  id: string
  properties: {
    email: string
    stripe_session_id: string
    client_reference_id?: string
  }
  archived: boolean
  createdAt: string
  updatedAt: string
}

export interface HubSpotTimelineEventResponse {
  id: string
  objectId: string
  eventTemplateId: string
  tokens: {
    stripeSessionId: string
    customerEmail: string
  }
  createdAt: string
  updatedAt: string
}

export interface HandleResult {
  contactId: string
  timelineEventId: string
}

async function hubspotRequest<T>(
  config: ConnectorConfig,
  method: string,
  url: string,
  body?: unknown,
  headers?: Record<string, string>
): Promise<T> {
  const fetchFn = config.fetch ?? fetch
  const requestHeaders = new Headers({
    'Authorization': `Bearer ${config.hubspotAccessToken}`,
    'Content-Type': 'application/json',
    ...headers,
  })

  const response = await fetchFn(url, {
    method,
    headers: requestHeaders,
    body: body ? JSON.stringify(body) : undefined,
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for ${method} ${url} - ${text}`)
  }

  if (response.status === 204) {
    return undefined as T
  }

  return response.json() as Promise<T>
}

export async function handle(
  payload: StripeCheckoutSessionCompleted,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (!payload.id) {
    throw new Error('Missing required field: id (Stripe session ID)')
  }
  if (!payload.customer?.email) {
    throw new Error('Missing required field: customer.email')
  }

  const sessionId = payload.id
  const customerEmail = payload.customer.email
  const clientReferenceId = payload.client_reference_id

  // Step 1: Create or update HubSpot contact using email as identifier
  const contactUrl = `https://api.hubapi.com/crm/v3/objects/contacts/${encodeURIComponent(customerEmail)}?idProperty=email`
  const contactBody = {
    properties: {
      email: customerEmail,
      stripe_session_id: sessionId,
      ...(clientReferenceId && { client_reference_id: clientReferenceId }),
    },
  }

  const contactResponse = await hubspotRequest<HubSpotContactResponse>(
    config,
    'PATCH',
    contactUrl,
    contactBody,
    { 'Idempotency-Key': sessionId }
  )

  const contactId = contactResponse.id

  // Step 2: Create timeline event
  const timelineUrl = 'https://api.hubapi.com/crm/v3/timeline/events'
  const timelineBody = {
    eventTemplateId: config.eventTemplateId,
    objectId: contactId,
    tokens: {
      stripeSessionId: sessionId,
      customerEmail: customerEmail,
    },
  }

  const timelineResponse = await hubspotRequest<HubSpotTimelineEventResponse>(
    config,
    'POST',
    timelineUrl,
    timelineBody
  )

  return {
    contactId,
    timelineEventId: timelineResponse.id,
  }
}

